window.AUTH=window.AUTH||{};window.AUTH["22-6389"]={"d":"22-6389","id":"2023/22-6389","n":"Brown v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Justin Rashaad Brown (as to 22-6389)","date":"2023-07-12","url":"https://www.supremecourt.gov/DocketPDF/22/22-6389/271910/20230712140735490_Brown%20-%20Opening%20Brief_Final_A.pdf","side":"pet","n":70},{"k":"petitioner","label":"Brief of petitioner Eugene Jackson (as to 22-6640)","date":"2023-07-12","url":"https://www.supremecourt.gov/DocketPDF/22/22-6389/271908/20230712135912426_22-6640%20ts.pdf","side":"pet","n":81},{"k":"respondent","label":"Brief of respondent United States","date":"2023-08-21","url":"https://www.supremecourt.gov/DocketPDF/22/22-6389/275741/20230821104804694_Nos.%2022-6389%20%2022-6640%20Brown%20%20Jackson%20v.%20USA.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner Justin Rashaad Brown (as to 22-6389)","date":"2023-09-20","url":"https://www.supremecourt.gov/DocketPDF/22/22-6389/280068/20230920171608129_Brown%20-%20Reply%20Brief.pdf","side":"pet","n":52},{"k":"reply","label":"Reply of petitioner Eugene Jackson (as to 22-6640)","date":"2023-09-20","url":"https://www.supremecourt.gov/DocketPDF/22/22-6389/279975/20230920123642198_Reply%20Brief.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r25_p86b.pdf","tr":true,"items":[{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"ar":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"0":"29","3":"7"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"op":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"21","1":"25, 33","2":"36","3":"11"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"37"}},{"t":"case","label":"Bittner v. United States","cite":"143 S. Ct. 713","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15","3":"9"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Borden v. United States","cite":"141 S. Ct. 1817","y":2021,"id":"2020/19-5410","sc":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5, 6, 16, 18","2":"33","3":"16"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Bradley v. Sch. Bd. of Richmond","cite":"416 U.S. 696","y":1974,"id":"1973/72-1322","sc":1,"sum":"Section 718 can be applied to attorneys' services that were rendered before that provision was enacted, in a situation like the one here involved where the propriety of the fee award was pending resolution on appeal when the statute became law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Concepcion v. United States","cite":"142 S. Ct. 2389","y":2022,"id":"2021/20-1650","sc":1,"ar":1,"sum":"Section 404(b) of the First Step Act of 2018, 132 Stat. 5222, allows district courts to consider intervening changes of law or fact in exercising their discretion to reduce a sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"9, 17, 20","3":"10"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"op":3,"ar":3,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"0":"9, 20, 21, 28","1":"9, 17, 18, 32, 33","2":"43","3":"7, 13","4":"7"}},{"t":"case","label":"El Encanto, Inc. v. Hatch Chile Co.","cite":"825 F.3d 1161","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/825/1161/","by":{"0":"12"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"op":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14"}},{"t":"case","label":"Granite Rock Co. v. Int’l Bhd. of Teamsters","cite":"561 U.S. 287","y":2010,"id":"2009/08-1214","sc":1,"sum":"The Court held that federal courts have jurisdiction to determine whether or not a collective bargaining agreement was formed between two parties when the agreement is disputed, but neither party makes a challenge to the arbitration clause contained in the agreement.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Page Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Found., Inc.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"op":1,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Hampton v. United States","cite":"191 F.3d 695","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/191/695/","by":{"0":"29"}},{"t":"case","label":"Jam v. Int’l Fin. Corp.","cite":"139 S. Ct. 759","y":2019,"id":"2018/17-1011","sc":1,"sum":"The International Organizations Immunities Act of 1945 affords international organizations the same immunity from suit that foreign governments enjoy today under the Foreign Sovereign Immunities Act of 1976.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"8, 11, 12","1":"31, 32","2":"41, 42","3":"4","4":"14"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"op":3,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19"}},{"t":"case","label":"Mathis v. United States","cite":"579 U.S. 500","y":2016,"id":"2015/15-6092","sc":1,"op":4,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"0":"5, 25","2":"6","3":"17","4":"16"}},{"t":"case","label":"McNeill v. United States","cite":"563 U.S. 816","y":2011,"id":"2010/10-5258","sc":1,"op":18,"ar":20,"sum":"The Court held that a federal sentencing court must determine whether an offense under state law is a \"serious drug offense\" within the meaning of the Armed Career Criminal Act by consulting the maximum sentence applicable at the time of the defendant's conviction.","sumSrc":"Oyez","by":{"0":"10, 12, 16, 26, 27","1":"6–8, 10, 11, 16, 21–24, 36","2":"9, 10, 12, 14-16, 18-22, 26, 27, 29-33, 37, 39, 41, 44","3":"4, 5, 6, 17","4":"2, 4, 5, 7, 8, 12, 14"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"sum":"A case in which the Court interpreted the parenthetical phrase “not to exceed 25 percent,” as used in 42 U.S.C. § 1997e(d)(2), to mean exactly 25 percent, thereby precluding the district court from exercising its discretion to allocate a lower percentage of the damage award to attorney's fees.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"N.H. Hemp Council, Inc. v. Marshall","cite":"203 F.3d 1","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/203/1/","op":2,"sum":"Noting that “the threat of federal prosecution [was] realistic” when hemp was still Jackson, J., dissenting on the federal schedules.","sumSrc":"opinion","by":{"0":"14"}},{"t":"case","label":"Oregon v. Ice","cite":"555 U.S. 160","y":2009,"id":"2008/07-901","sc":1,"sum":"The Court found that the Sixth Amendment can assign judges, rather than juries, the responsibility of fact-finding in order to impose consecutive sentences on criminal defendants.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Ovalles v. United States","cite":"905 F.3d 1231","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/905/1231/","by":{"0":"24","3":"17"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"sum":"The Court held that when a defendant's sentence has been set aside on appeal, a district court may consider evidence of the defendant's rehabilitation after the initial sentences, which may support lesser sentencing guidelines.","sumSrc":"Oyez","by":{"0":"18","3":"11"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"0":"18","3":"9"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14","2":"6","3":"13"}},{"t":"case","label":"Rosales-Mireles v. United States","cite":"138 S. Ct. 1897","y":2018,"id":"2017/16-9493","sc":1,"sum":"The Court held that a miscalculation of a Federal Guidelines sentencing range that has been determined to be plain and to affect a defendant’s substantial rights calls for a court of appeals to exercise its discretion under Federal Rule of Criminal Procedure 52(b) to vacate the defendant’s sentence in the ordinary case.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"op":6,"ar":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"0":"12","1":"4, 9, 11, 16, 17, 22, 23, 36, 37","2":"6, 20, 23, 24, 33, 43","3":"8","4":"7, 16, 17"}},{"t":"case","label":"Page Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"op":5,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 5, 23, 27","1":"25","2":"3, 6"}},{"t":"case","label":"Thorpe v. Hous. Auth. of Durham","cite":"393 U.S. 268","y":1969,"id":"1968/20","sc":1,"sum":"The Court also decided that the circular was mandatory, not advisory, and it was not an unconstitutional impairment of the Housing Authorities lease agreement. Justice Hugo L. Black wrote a special concurrence stating that because the Housing Authority admitted to following the circular nothing needed to be decided other than that the circular applied in this case.","sumSrc":"Oyez","by":{"0":"8, 18"}},{"t":"case","label":"Touby v. United States","cite":"500 U.S. 160","y":1991,"id":"1990/90-6282","sc":1,"sum":"The Court held that the Controlled Substances Act allows the Attorney General to delegate authority to the Drug Enforcement Agency.","sumSrc":"Oyez","by":{"0":"4","1":"13"}},{"t":"case","label":"United States v. Abdulaziz","cite":"998 F.3d 519","y":2021,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/998/519/","by":{"0":"13, 22","2":"34","3":"20"}},{"t":"case","label":"United States v. Aguila-Montes de Oca","cite":"655 F.3d 915","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/915/","by":{"0":"25"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"37"}},{"t":"case","label":"United States v. Bautista","cite":"989 F.3d 698","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/989/698/","op":1,"by":{"0":"11","1":"26"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"sum":"In 1963, respondent was convicted of first-degree murder and sentenced to death by a jury in the Federal District Court for the District of Columbia, which at that time had exclusive jurisdiction over local felonies committed in the District. The Court of Appeals for the District of Columbia Circuit, which then acted as the local appellate court, upheld the conviction but set aside the death sentence, and respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Gibson","cite":"55 F.4th 153","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/55/153/","by":{"0":"4, 12","3":"4"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"op":2,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"United States v. James","cite":"846 F. App’x 395","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/846/395/","by":{"0":"22"}},{"t":"case","label":"United States v. Johnson","cite":"704 F. Supp. 1403","y":1989,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp./704/1403/","by":{"0":"13"}},{"t":"case","label":"United States v. Roach","cite":"958 F.2d 679","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/958/679/","by":{"0":"13"}},{"t":"case","label":"United States v. Rodriguez","cite":"553 U.S. 377","y":2008,"id":"2007/06-1646","sc":1,"op":1,"sum":"The Court held 6-3 that although the elements of a particular crime may not be considered \"serious,\" a defendant's prior record will have a considerable bearing on making the determination. A crime's seriousness may be greatly enhanced when its maximum sentence is increased due to the defendant's prior convictions for similar or related crimes.","sumSrc":"Oyez","by":{"0":"21","1":"24, 26","2":"39, 40","4":"12"}},{"t":"case","label":"United States v. Vermont","cite":"317 F.2d 446","y":1963,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/317/446/","by":{"0":"15"}},{"t":"case","label":"Page United States v. White Plume","cite":"447 F.3d 1067","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/447/1067/","by":{"0":"14"}},{"t":"case","label":"Wachovia Bank, Nat’l Ass’n v. Schmidt","cite":"546 U.S. 303","y":2006,"id":"2005/04-1186","sc":1,"sum":"The Court ruled that a national bank is \"located\" in, and therefore a \"citizen\" of, only the state in which its main office is located. Looking to the history of Congress's diversity jurisdiction statutes, the Court concluded that the word \"located\" need not be interpreted to mean any state where a bank has a physical presence.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"15"}},{"t":"law","label":"AND REGULATIONS, Pub. L. No. 91-513","url":"https://www.govinfo.gov/link/statute/84/1236","by":{"0":"22","1":"4, 5, 7, 14, 16, 36, 21","2":"28, 28","4":"3–4, 9, 10, 14, 15"}},{"t":"law","label":"Pub. L. No. 115-334","url":"https://www.govinfo.gov/link/plaw/115/public/334","by":{"0":"6, 29","1":"27","2":"8"}},{"t":"usc","label":"1 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/1/109","stext":{"head":"§109. Repeal of statutes as affecting existing liabilities","paras":[[0,"The repeal of any statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the repealing Act shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability. The expiration of a temporary statute shall not have the effect to release or extinguish any penalty, forfeiture, or liability incurred under such statute, unless the temporary statute shall so expressly provide, and such statute shall be treated as still remaining in force for the purpose of sustaining any proper action or prosecution for the enforcement of such penalty, forfeiture, or liability."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/109?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§109. Repeal of statutes as affecting existing liabilities","tname":"General Provisions","by":{"0":"3, 7, 10, 29","1":"17","2":"9","3":"10"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(20)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"head":"§921. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"13, 29","2":"15, 22, 25, 26","4":"6"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(1)","(e)(2)(A)(ii)","(e)(2)(B)(ii)","(e)(2)(A)(i)","(g)(3)","(a)(8)","(e)(2)(A)","(e)(2)(A)(ii)(2012)","(a)(2)(2012)","(a)(2)(2018)","(c)(1)(A)","(c)(1)(C)","(c)(5)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":12,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"4, 29, 4, 5, 7, 8, 11, 12, 13, 14, 15, 16, 19, 26, 14","1":"i, 1–38, 3, 36, 37, i, 3, 4, 9, 12–16, 18–23, 37, 14, 3","2":"3, 40, 40, 40, 40, 40, 40, 4, 4, 4, 26, 7, 27","3":"8, 2, 3, 4, 8","4":"3, 17, 17, 17, 5, 17, 16, 17, 18, 3, 4, 5, 9, 16, 17, 3"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)(1)","(a)(4)(A)(ii)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"22, 21","2":"44","3":"7"}},{"t":"usc","label":"18 U.S.C. § 3559","url":"https://www.law.cornell.edu/uscode/text/18/3559","subs":["(c)(2)(H)(ii)","(c)","(c)(2)"],"stext":{"head":"§3559. Sentencing classification of offenses","paras":[[0,"(a) Classification.—An offense that is not specifically classified by a letter grade in the section defining it, is classified if the maximum term of imprisonment authorized is—"],[1,"(1) life imprisonment, or if the maximum penalty is death, as a Class A felony;"],[1,"(2) twenty-five years or more, as a Class B felony;"],[1,"(3) less than twenty-five years but ten or more years, as a Class C felony;"],[1,"(4) less than ten years but five or more years, as a Class D felony;"],[1,"(5) less than five years but more than one year, as a Class E felony;"],[1,"(6) one year or less but more than six months, as a Class A misdemeanor;"],[1,"(7) six months or less but more than thirty days, as a Class B misdemeanor;"],[1,"(8) thirty days or less but more than five days, as a Class C misdemeanor; or"],[1,"(9) five days or less, or if no imprisonment is authorized, as an infraction."],[0,"(b) Effect of Classification.—Except as provided in subsection (c), an offense classified under subsection (a) carries all the incidents assigned to the applicable letter designation, except that the maximum term of imprisonment is the term authorized by the law describing the offense."],[0,"(c) Imprisonment of Certain Violent Felons.—"],[1,"(1) Mandatory life imprisonment.—Notwithstanding any other provision of law, a person who is convicted in a court of the United States of a serious violent felony shall be sentenced to life imprisonment if—"],[2,"(A) the person has been convicted (and those convictions have become final) on separate prior occasions in a court of the United States or of a State of—"],[3,"(i) 2 or more serious violent felonies; or"],[3,"(ii) one or more serious violent felonies and one or more serious drug offenses; and"],[2,"(B) each serious violent felony or serious drug offense used as a basis for sentencing under this subsection, other than the first, was committed after the defendant's conviction of the preceding serious violent felony or serious drug offense."],[1,"(2) Definitions.—For purposes of this subsection—"],[2,"(A) the term \"assault with intent to commit rape\" means an offense that has as its elements engaging in physical contact with another person or using or brandishing a weapon against another person with intent to commit aggravated sexual abuse or sexual abuse (as described in sections 2241 and 2242);"],[2,"(B) the term \"arson\" means an offense that has as its elements maliciously damaging or destroying any building, inhabited structure, vehicle, vessel, or real property by means of fire or an explosive;"],[2,"(C) the term \"extortion\" means an offense that has as its elements the extraction of anything of value from another person by threatening or placing that person in fear of injury to any person or kidnapping of any person;"],[2,"(D) the term \"firearms use\" means an offense that has as its elements those described in section 924(c) or 929(a), if the firearm was brandished, discharged, or otherwise used as a weapon and the crime of violence or drug trafficking crime during and relation to which the firearm was used was subject to prosecution in a court of the United States or a court of a State, or both;"],[2,"(E) the term \"kidnapping\" means an offense that has as its elements the abduction, restraining, confining, or carrying away of another person by force or threat of force;"],[2,"(F) the term \"serious violent felony\" means—"],[3,"(i) a Federal or State offense, by whatever designation and wherever committed, consisting of murder (as described in section 1111); manslaughter other than involuntary manslaughter (as described in section 1112); assault with intent to commit murder (as described in section 113(a)); assault with intent to commit rape; aggravated sexual abuse and sexual abuse (as described in sections 2241 and 2242); abusive sexual contact (as described in sections 2244(a)(1) and (a)(2)); kidnapping; aircraft piracy (as described in section 46502 of Title 49); robbery (as described in section 2111, 2113, or 2118); carjacking (as described in section 2119); extortion; arson; firearms use; firearms possession (as described in section 924(c)); or attempt, conspiracy, or solicitation to commit any of the above offenses; and"],[3,"(ii) any other offense punishable by a maximum term of imprisonment of 10 years or more that has as an element the use, attempted use, or threatened use of physical force against the person of another or that, by its nature, involves a substantial risk that physical force against the person of another may be used in the course of committing the offense;"],[2,"(G) the term \"State\" means a State of the United States, the District of Columbia, and a commonwealth, territory, or possession of the United States; and"],[2,"(H) the term \"serious drug offense\" means—"],[3,"(i) an offense that is punishable under section 401(b)(1)(A) or 408 of the Controlled Substances Act (21 U.S.C. 841(b)(1)(A), 848) or section 1010(b)(1)(A) of the Controlled Substances Import and Export Act (21 U.S.C. 960(b)(1)(A)); or"],[3,"(ii) an offense under State law that, had the offense been prosecuted in a court of the United States, would have been punishable under section 401(b)(1)(A) or 408 of the Controlled Substances Act (21 U.S.C. 841(b)(1)(A), 848) or section 1010(b)(1)(A) of the Controlled Substances Import and Export Act (21 U.S.C. 960(b)(1)(A))."],[1,"(3) Nonqualifying felonies.—"],[2,"(A) Robbery in certain cases.—Robbery, an attempt, conspiracy, or solicitation to commit robbery; or an offense described in paragraph (2)(F)(ii) shall not serve as a basis for sentencing under this subsection if the defendant establishes by clear and convincing evidence that—"],[3,"(i) no firearm or other dangerous weapon was used in the offense and no threat of use of a firearm or other dangerous weapon was involved in the offense; and"],[3,"(ii) the offense did not result in death or serious bodily injury (as defined in section 1365) to any person."],[2,"(B) Arson in certain cases.—Arson shall not serve as a basis for sentencing under this subsection if the defendant establishes by clear and convincing evidence that—"],[3,"(i) the offense posed no threat to human life; and"],[3,"(ii) the defendant reasonably believed the offense posed no threat to human life."],[1,"(4) Information filed by united states attorney.—The provisions of section 411(a) of the Controlled Substances Act (21 U.S.C. 851(a)) shall apply to the imposition of sentence under this subsection."],[1,"(5) Rule of construction.—This subsection shall not be construed to preclude imposition of the death penalty."],[1,"(6) Special provision for indian country.—No person subject to the criminal jurisdiction of an Indian tribal government shall be subject to this subsection for any offense for which Federal jurisdiction is solely predicated on Indian country (as defined in section 1151) and which occurs within the boundaries of such Indian country unless the governing body of the tribe has elected that this subsection have effect over land and persons subject to the criminal jurisdiction of the tribe."],[1,"(7) Resentencing upon overturning of prior conviction.—If the conviction for a serious violent felony or serious drug offense that was a basis for sentencing under this subsection is found, pursuant to any appropriate State or Federal procedure, to be unconstitutional or is vitiated on the explicit basis of innocence, or if the convicted person is pardoned on the explicit basis of innocence, the person serving a sentence imposed under this subsection shall be resentenced to any sentence that was available at the time of the original sentencing."],[0,"(d) Death or Imprisonment for Crimes Against Children.—"],[1,"(1) In general.—Subject to paragraph (2) and notwithstanding any other provision of law, a person who is convicted of a Federal offense that is a serious violent felony (as defined in subsection (c)) or a violation of section 2422, 2423, or 2251 shall, unless the sentence of death is imposed, be sentenced to imprisonment for life, if—"],[2,"(A) the victim of the offense has not attained the age of 14 years;"],[2,"(B) the victim dies as a result of the offense; and"],[2,"(C) the defendant, in the course of the offense, engages in conduct described in section 3591(a)(2)."],[1,"(2) Exception.—With respect to a person convicted of a Federal offense described in paragraph (1), the court may impose any lesser sentence that is authorized by law to take into account any substantial assistance provided by the defendant in the investigation or prosecution of another person who has committed an offense, in accordance with the Federal Sentencing Guidelines and the policy statements of the Federal Sentencing Commission pursuant to section 994(p) of title 28, or for other good cause."],[0,"(e) Mandatory Life Imprisonment for Repeated Sex Offenses Against Children.—"],[1,"(1) In general.—A person who is convicted of a Federal sex offense in which a minor is the victim shall be sentenced to life imprisonment if the person has a prior sex conviction in which a minor was the victim, unless the sentence of death is imposed."],[1,"(2) Definitions.—For the purposes of this subsection—"],[2,"(A) the term \"Federal sex offense\" means an offense under section 1591 (relating to sex trafficking of children), 2241 (relating to aggravated sexual abuse), 2242 (relating to sexual abuse), 2244(a)(1) (relating to abusive sexual contact), 2245 (relating to sexual abuse resulting in death), 2251 (relating to sexual exploitation of children), 2251A (relating to selling or buying of children), 2422(b) (relating to coercion and enticement of a minor into prostitution), or 2423(a) (relating to transportation of minors);"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3559?type=usc&year=mostrecent&link-type=html"},"head":"§3559. Sentencing classification of offenses","tname":"Crimes and Criminal Procedure","by":{"0":"15","1":"16","2":"26, 27, 26","3":"8","4":"4"}},{"t":"usc","label":"21 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/21/802","subs":["(6)","(57)"],"stext":{"head":"§802. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) The term \"addict\" means any individual who habitually uses any narcotic drug so as to endanger the public morals, health, safety, or welfare, or who is so far addicted to the use of narcotic drugs as to have lost the power of self-control with reference to his addiction."],[0,"(2) The term \"administer\" refers to the direct application of a controlled substance to the body of a patient or research subject by—"],[1,"(A) a practitioner (or, in his presence, by his authorized agent), or"],[1,"(B) the patient or research subject at the direction and in the presence of the practitioner,"],[0,"whether such application be by injection, inhalation, ingestion, or any other means."],[0,"(3) The term \"agent\" means an authorized person who acts on behalf of or at the direction of a manufacturer, distributor, or dispenser; except that such term does not include a common or contract carrier, public warehouseman, or employee of the carrier or warehouseman, when acting in the usual and lawful course of the carrier's or warehouseman's business."],[0,"(4) The term \"Drug Enforcement Administration\" means the Drug Enforcement Administration in the Department of Justice."],[0,"(5) The term \"control\" means to add a drug or other substance, or immediate precursor, to a schedule under part B of this subchapter, whether by transfer from another schedule or otherwise."],[0,"(6) The term \"controlled substance\" means a drug or other substance, or immediate precursor, included in schedule I, II, III, IV, or V of part B of this subchapter. The term does not include distilled spirits, wine, malt beverages, or tobacco, as those terms are defined or used in subtitle E of the Internal Revenue Code of 1986."],[0,"(7) The term \"counterfeit substance\" means a controlled substance which, or the container or labeling of which, without authorization, bears the trademark, trade name, or other identifying mark, imprint, number, or device, or any likeness thereof, of a manufacturer, distributor, or dispenser other than the person or persons who in fact manufactured, distributed, or dispensed such substance and which thereby falsely purports or is represented to be the product of, or to have been distributed by, such other manufacturer, distributor, or dispenser."],[0,"(8) The terms \"deliver\" or \"delivery\" mean the actual, constructive, or attempted transfer of a controlled substance or a listed chemical, whether or not there exists an agency relationship."],[0,"(9) The term \"depressant or stimulant substance\" means—"],[1,"(A) a drug which contains any quantity of barbituric acid or any of the salts of barbituric acid; or"],[1,"(B) a drug which contains any quantity of (i) amphetamine or any of its optical isomers; (ii) any salt of amphetamine or any salt of an optical isomer of amphetamine; or (iii) any substance which the Attorney General, after investigation, has found to be, and by regulation designated as, habit forming because of its stimulant effect on the central nervous system; or"],[1,"(C) lysergic acid diethylamide; or"],[1,"(D) any drug which contains any quantity of a substance which the Attorney General, after investigation, has found to have, and by regulation designated as having, a potential for abuse because of its depressant or stimulant effect on the central nervous system or its hallucinogenic effect."],[0,"(10) The term \"dispense\" means to deliver a controlled substance to an ultimate user or research subject by, or pursuant to the lawful order of, a practitioner, including the prescribing and administering of a controlled substance and the packaging, labeling or compounding necessary to prepare the substance for such delivery. The term \"dispenser\" means a practitioner who so delivers a controlled substance to an ultimate user or research subject."],[0,"(11) The term \"distribute\" means to deliver (other than by administering or dispensing) a controlled substance or a listed chemical. The term \"distributor\" means a person who so delivers a controlled substance or a listed chemical."],[0,"(12) The term \"drug\" has the meaning given that term by section 321(g)(1) of this title."],[0,"(13) The term \"felony\" means any Federal or State offense classified by applicable Federal or State law as a felony."],[0,"(14) The term \"isomer\" means the optical isomer, except as used in schedule I(c) and schedule II(a)(4). As used in schedule I(c), the term \"isomer\" means any optical, positional, or geometric isomer. As used in schedule II(a)(4), the term \"isomer\" means any optical or geometric isomer."],[0,"(15) The term \"manufacture\" means the production, preparation, propagation, compounding, or processing of a drug or other substance, either directly or indirectly or by extraction from substances of natural origin, or independently by means of chemical synthesis or by a combination of extraction and chemical synthesis, and includes any packaging or repackaging of such substance or labeling or relabeling of its container; except that such term does not include the preparation, compounding, packaging, or labeling of a drug or other substance in conformity with applicable State or local law by a practitioner as an incident to his administration or dispensing of such drug or substance in the course of his professional practice. The term \"manufacturer\" means a person who manufactures a drug or other substance."],[0,"(16)(A) Subject to subparagraph (B), the terms \"marihuana\" and \"marijuana\" mean all parts of the plant Cannabis sativa L., whether growing or not; the seeds thereof; the resin extracted from any part of such plant; and every compound, manufacture, salt, derivative, mixture, or preparation of such plant, its seeds or resin."],[0,"(B) The terms \"marihuana\" and \"marijuana\" do not include—"],[1,"(i) hemp, as defined in section 1639o of title 7; or"],[1,"(ii) the mature stalks of such plant, fiber produced from such stalks, oil or cake made from the seeds of such plant, any other compound, manufacture, salt, derivative, mixture, or preparation of such mature stalks (except the resin extracted therefrom), fiber, oil, or cake, or the sterilized seed of such plant which is incapable of germination."],[0,"(17) The term \"narcotic drug\" means any of the following whether produced directly or indirectly by extraction from substances of vegetable origin, or independently by means of chemical synthesis, or by a combination of extraction and chemical synthesis:"],[1,"(A) Opium, opiates, derivatives of opium and opiates, including their isomers, esters, ethers, salts, and salts of isomers, esters, and ethers, whenever the existence of such isomers, esters, ethers, and salts is possible within the specific chemical designation. Such term does not include the isoquinoline alkaloids of opium."],[1,"(B) Poppy straw and concentrate of poppy straw."],[1,"(C) Coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed."],[1,"(D) Cocaine, its salts, optical and geometric isomers, and salts of isomers."],[1,"(E) Ecgonine, its derivatives, their salts, isomers, and salts of isomers."],[1,"(F) Any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subparagraphs (A) through (E)."],[0,"(18) The term \"opiate\" or \"opioid\" means any drug or other substance having an addiction-forming or addiction-sustaining liability similar to morphine or being capable of conversion into a drug having such addiction-forming or addiction-sustaining liability."],[0,"(19) The term \"opium poppy\" means the plant of the species Papaver somniferum L., except the seed thereof."],[0,"(20) The term \"poppy straw\" means all parts, except the seeds, of the opium poppy, after mowing."],[0,"(21) The term \"practitioner\" means a physician, dentist, veterinarian, scientific investigator, pharmacy, hospital, or other person licensed, registered, or otherwise permitted, by the United States or the jurisdiction in which he practices or does research, to distribute, dispense, conduct research with respect to, administer, or use in teaching or chemical analysis, a controlled substance in the course of professional practice or research."],[0,"(22) The term \"production\" includes the manufacture, planting, cultivation, growing, or harvesting of a controlled substance."],[0,"(23) The term \"immediate precursor\" means a substance—"],[1,"(A) which the Attorney General has found to be and by regulation designated as being the principal compound used, or produced primarily for use, in the manufacture of a controlled substance;"],[1,"(B) which is an immediate chemical intermediary used or likely to be used in the manufacture of such controlled substance; and"],[1,"(C) the control of which is necessary to prevent, curtail, or limit the manufacture of such controlled substance."],[0,"(24) The term \"Secretary\", unless the context otherwise indicates, means the Secretary of Health and Human Services."],[0,"(25) The term \"serious bodily injury\" means bodily injury which involves—"],[1,"(A) a substantial risk of death;"],[1,"(B) protracted and obvious disfigurement; or"],[1,"(C) protracted loss or impairment of the function of a bodily member, organ, or mental faculty."],[0,"(26) The term \"State\" means a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/802?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§802. Definitions","tname":"Food and Drugs","by":{"0":"3, 12","1":"2, 4, 12, 14, 19–20, 34","2":"5","3":"4","4":"9, 15, 3"}},{"t":"usc","label":"21 U.S.C. § 811","url":"https://www.law.cornell.edu/uscode/text/21/811","subs":["(b)","(c)","(h)","(a)"],"stext":{"head":"§811. Authority and criteria for classification of substances","paras":[[0,"(a) Rules and regulations of Attorney General; hearing"],[0,"The Attorney General shall apply the provisions of this subchapter to the controlled substances listed in the schedules established by section 812 of this title and to any other drug or other substance added to such schedules under this subchapter. Except as provided in subsections (d) and (e), the Attorney General may by rule—"],[1,"(1) add to such a schedule or transfer between such schedules any drug or other substance if he—"],[2,"(A) finds that such drug or other substance has a potential for abuse, and"],[2,"(B) makes with respect to such drug or other substance the findings prescribed by subsection (b) of section 812 of this title for the schedule in which such drug is to be placed; or"],[1,"(2) remove any drug or other substance from the schedules if he finds that the drug or other substance does not meet the requirements for inclusion in any schedule."],[0,"Rules of the Attorney General under this subsection shall be made on the record after opportunity for a hearing pursuant to the rulemaking procedures prescribed by subchapter II of chapter 5 of title 5. Proceedings for the issuance, amendment, or repeal of such rules may be initiated by the Attorney General (1) on his own motion, (2) at the request of the Secretary, or (3) on the petition of any interested party."],[0,"(b) Evaluation of drugs and other substances"],[0,"The Attorney General shall, before initiating proceedings under subsection (a) to control a drug or other substance or to remove a drug or other substance entirely from the schedules, and after gathering the necessary data, request from the Secretary a scientific and medical evaluation, and his recommendations, as to whether such drug or other substance should be so controlled or removed as a controlled substance. In making such evaluation and recommendations, the Secretary shall consider the factors listed in paragraphs (2), (3), (6), (7), and (8) of subsection (c) and any scientific or medical considerations involved in paragraphs (1), (4), and (5) of such subsection. The recommendations of the Secretary shall include recommendations with respect to the appropriate schedule, if any, under which such drug or other substance should be listed. The evaluation and the recommendations of the Secretary shall be made in writing and submitted to the Attorney General within a reasonable time. The recommendations of the Secretary to the Attorney General shall be binding on the Attorney General as to such scientific and medical matters, and if the Secretary recommends that a drug or other substance not be controlled, the Attorney General shall not control the drug or other substance. If the Attorney General determines that these facts and all other relevant data constitute substantial evidence of potential for abuse such as to warrant control or substantial evidence that the drug or other substance should be removed entirely from the schedules, he shall initiate proceedings for control or removal, as the case may be, under subsection (a)."],[0,"(c) Factors determinative of control or removal from schedules"],[0,"In making any finding under subsection (a) of this section or under subsection (b) of section 812 of this title, the Attorney General shall consider the following factors with respect to each drug or other substance proposed to be controlled or removed from the schedules:"],[1,"(1) Its actual or relative potential for abuse."],[1,"(2) Scientific evidence of its pharmacological effect, if known."],[1,"(3) The state of current scientific knowledge regarding the drug or other substance."],[1,"(4) Its history and current pattern of abuse."],[1,"(5) The scope, duration, and significance of abuse."],[1,"(6) What, if any, risk there is to the public health."],[1,"(7) Its psychic or physiological dependence liability."],[1,"(8) Whether the substance is an immediate precursor of a substance already controlled under this subchapter."],[0,"(d) International treaties, conventions, and protocols requiring control; procedures respecting changes in drug schedules of Convention on Psychotropic Substances"],[0,"(1) If control is required by United States obligations under international treaties, conventions, or protocols in effect on October 27, 1970, the Attorney General shall issue an order controlling such drug under the schedule he deems most appropriate to carry out such obligations, without regard to the findings required by subsection (a) of this section or section 812(b) of this title and without regard to the procedures prescribed by subsections (a) and (b) of this section."],[0,"(2)(A) Whenever the Secretary of State receives notification from the Secretary-General of the United Nations that information has been transmitted by or to the World Health Organization, pursuant to article 2 of the Convention on Psychotropic Substances, which may justify adding a drug or other substance to one of the schedules of the Convention, transferring a drug or substance from one schedule to another, or deleting it from the schedules, the Secretary of State shall immediately transmit the notice to the Secretary of Health and Human Services who shall publish it in the Federal Register and provide opportunity to interested persons to submit to him comments respecting the scientific and medical evaluations which he is to prepare respecting such drug or substance. The Secretary of Health and Human Services shall prepare for transmission through the Secretary of State to the World Health Organization such medical and scientific evaluations as may be appropriate regarding the possible action that could be proposed by the World Health Organization respecting the drug or substance with respect to which a notice was transmitted under this subparagraph."],[0,"(B) Whenever the Secretary of State receives information that the Commission on Narcotic Drugs of the United Nations proposes to decide whether to add a drug or other substance to one of the schedules of the Convention, transfer a drug or substance from one schedule to another, or delete it from the schedules, the Secretary of State shall transmit timely notice to the Secretary of Health and Human Services of such information who shall publish a summary of such information in the Federal Register and provide opportunity to interested persons to submit to him comments respecting the recommendation which he is to furnish, pursuant to this subparagraph, respecting such proposal. The Secretary of Health and Human Services shall evaluate the proposal and furnish a recommendation to the Secretary of State which shall be binding on the representative of the United States in discussions and negotiations relating to the proposal."],[0,"(3) When the United States receives notification of a scheduling decision pursuant to article 2 of the Convention on Psychotropic Substances that a drug or other substance has been added or transferred to a schedule specified in the notification or receives notification (referred to in this subsection as a \"schedule notice\") that existing legal controls applicable under this subchapter to a drug or substance and the controls required by the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] do not meet the requirements of the schedule of the Convention in which such drug or substance has been placed, the Secretary of Health and Human Services after consultation with the Attorney General, shall first determine whether existing legal controls under this subchapter applicable to the drug or substance and the controls required by the Federal Food, Drug, and Cosmetic Act, meet the requirements of the schedule specified in the notification or schedule notice and shall take the following action:"],[1,"(A) If such requirements are met by such existing controls but the Secretary of Health and Human Services nonetheless believes that more stringent controls should be applied to the drug or substance, the Secretary shall recommend to the Attorney General that he initiate proceedings for scheduling the drug or substance, pursuant to subsections (a) and (b) of this section, to apply to such controls."],[1,"(B) If such requirements are not met by such existing controls and the Secretary of Health and Human Services concurs in the scheduling decision or schedule notice transmitted by the notification, the Secretary shall recommend to the Attorney General that he initiate proceedings for scheduling the drug or substance under the appropriate schedule pursuant to subsections (a) and (b) of this section."],[1,"(C) If such requirements are not met by such existing controls and the Secretary of Health and Human Services does not concur in the scheduling decision or schedule notice transmitted by the notification, the Secretary shall—"],[2,"(i) if he deems that additional controls are necessary to protect the public health and safety, recommend to the Attorney General that he initiate proceedings for scheduling the drug or substance pursuant to subsections (a) and (b) of this section, to apply such additional controls;"],[2,"(ii) request the Secretary of State to transmit a notice of qualified acceptance, within the period specified in the Convention, pursuant to paragraph 7 of article 2 of the Convention, to the Secretary-General of the United Nations;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/811?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§811. Authority and criteria for classification of substances","tname":"Food and Drugs","by":{"0":"4","1":"1, 13, 13","2":"5, 39, 41, 42"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","subs":["(a)","(b)(2)(B)","(c)"],"stext":{"head":"§812. Schedules of controlled substances","paras":[[0,"(a) Establishment"],[0,"There are established five schedules of controlled substances, to be known as schedules I, II, III, IV, and V. Such schedules shall initially consist of the substances listed in this section. The schedules established by this section shall be updated and republished on a semiannual basis during the two-year period beginning one year after October 27, 1970, and shall be updated and republished on an annual basis thereafter.1"],[0,"(b) Placement on schedules; findings required"],[0,"Except where control is required by United States obligations under an international treaty, convention, or protocol, in effect on October 27, 1970, and except in the case of an immediate precursor, a drug or other substance may not be placed in any schedule unless the findings required for such schedule are made with respect to such drug or other substance. The findings required for each of the schedules are as follows:"],[0,"(1) Schedule I.—"],[1,"(A) The drug or other substance has a high potential for abuse."],[1,"(B) The drug or other substance has no currently accepted medical use in treatment in the United States."],[1,"(C) There is a lack of accepted safety for use of the drug or other substance under medical supervision."],[0,"(2) Schedule II.—"],[1,"(A) The drug or other substance has a high potential for abuse."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States or a currently accepted medical use with severe restrictions."],[1,"(C) Abuse of the drug or other substances may lead to severe psychological or physical dependence."],[0,"(3) Schedule III.—"],[1,"(A) The drug or other substance has a potential for abuse less than the drugs or other substances in schedules I and II."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to moderate or low physical dependence or high psychological dependence."],[0,"(4) Schedule IV.—"],[1,"(A) The drug or other substance has a low potential for abuse relative to the drugs or other substances in schedule III."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to limited physical dependence or psychological dependence relative to the drugs or other substances in schedule III."],[0,"(5) Schedule V.—"],[1,"(A) The drug or other substance has a low potential for abuse relative to the drugs or other substances in schedule IV."],[1,"(B) The drug or other substance has a currently accepted medical use in treatment in the United States."],[1,"(C) Abuse of the drug or other substance may lead to limited physical dependence or psychological dependence relative to the drugs or other substances in schedule IV."],[0,"(c) Initial schedules of controlled substances"],[0,"Schedules I, II, III, IV, and V shall, unless and until amended pursuant to section 811 of this title, consist of the following drugs or other substances,1 by whatever official name, common or usual name, chemical name, or brand name designated:"],[0,"(a) Unless specifically excepted or unless listed in another schedule, any of the following opiates, including their isomers, esters, ethers, salts, and salts of isomers, esters, and ethers, whenever the existence of such isomers, esters, ethers, and salts is possible within the specific chemical designation:"],[1,"(1) Acetylmethadol."],[1,"(2) Allylprodine."],[1,"(3) Alphacetylmathadol.2"],[1,"(4) Alphameprodine."],[1,"(5) Alphamethadol."],[1,"(6) Benzethidine."],[1,"(7) Betacetylmethadol."],[1,"(8) Betameprodine."],[1,"(9) Betamethadol."],[1,"(10) Betaprodine."],[1,"(11) Clonitazene."],[1,"(12) Dextromoramide."],[1,"(13) Dextrorphan."],[1,"(14) Diampromide."],[1,"(15) Diethylthiambutene."],[1,"(16) Dimenoxadol."],[1,"(17) Dimepheptanol."],[1,"(18) Dimethylthiambutene."],[1,"(19) Dioxaphetyl butyrate."],[1,"(20) Dipipanone."],[1,"(21) Ethylmethylthiambutene."],[1,"(22) Etonitazene."],[1,"(23) Etoxeridine."],[1,"(24) Furethidine."],[1,"(25) Hydroxypethidine."],[1,"(26) Ketobemidone."],[1,"(27) Levomoramide."],[1,"(28) Levophenacylmorphan."],[1,"(29) Morpheridine."],[1,"(30) Noracymethadol."],[1,"(31) Norlevorphanol."],[1,"(32) Normethadone."],[1,"(33) Norpipanone."],[1,"(34) Phenadoxone."],[1,"(35) Phenampromide."],[1,"(36) Phenomorphan."],[1,"(37) Phenoperidine."],[1,"(38) Piritramide."],[1,"(39) Proheptazine."],[1,"(40) Properidine."],[1,"(41) Racemoramide."],[1,"(42) Trimeperidine."],[0,"(b) Unless specifically excepted or unless listed in another schedule, any of the following opium derivatives, their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation:"],[1,"(1) Acetorphine."],[1,"(2) Acetyldihydrocodeine."],[1,"(3) Benzylmorphine."],[1,"(4) Codeine methylbromide."],[1,"(5) Codeine-N-Oxide."],[1,"(6) Cyprenorphine."],[1,"(7) Desomorphine."],[1,"(8) Dihydromorphine."],[1,"(9) Etorphine."],[1,"(10) Heroin."],[1,"(11) Hydromorphinol."],[1,"(12) Methyldesorphine."],[1,"(13) Methylhydromorphine."],[1,"(14) Morphine methylbromide."],[1,"(15) Morphine methylsulfonate."],[1,"(16) Morphine-N-Oxide."],[1,"(17) Myrophine."],[1,"(18) Nicocodeine."],[1,"(19) Nicomorphine."],[1,"(20) Normorphine."],[1,"(21) Pholcodine."],[1,"(22) Thebacon."],[0,"(c) Unless specifically excepted or unless listed in another schedule, any material, compound, mixture, or preparation, which contains any quantity of the following hallucinogenic substances, or which contains any of their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation:"],[1,"(1) 3,4-methylenedioxy amphetamine."],[1,"(2) 5-methoxy-3,4-methylenedioxy amphetamine."],[1,"(3) 3,4,5-trimethoxy amphetamine."],[1,"(4) Bufotenine."],[1,"(5) Diethyltryptamine."],[1,"(6) Dimethyltryptamine."],[1,"(7) 4-methyl-2,5-dimethoxyamphetamine."],[1,"(8) Ibogaine."],[1,"(9) Lysergic acid diethylamide."],[1,"(10) Marihuana."],[1,"(11) Mescaline."],[1,"(12) Peyote."],[1,"(13) N-ethyl-3-piperidyl benzilate."],[1,"(14) N-methyl-3-piperidyl benzilate."],[1,"(15) Psilocybin."],[1,"(16) Psilocyn."],[1,"(17) Tetrahydrocannabinols, except for tetrahydrocannabinols in hemp (as defined under section 1639o of title 7)."],[1,"(18) 4-methylmethcathinone (Mephedrone)."],[1,"(19) 3,4-methylenedioxypyrovalerone (MDPV)."],[1,"(20) 2-(2,5-Dimethoxy-4-ethylphenyl)ethanamine (2C–E)."],[1,"(21) 2-(2,5-Dimethoxy-4-methylphenyl)ethanamine (2C–D)."],[1,"(22) 2-(4-Chloro-2,5-dimethoxyphenyl)ethanamine (2C–C)."],[1,"(23) 2-(4-Iodo-2,5-dimethoxyphenyl)ethanamine (2C–I)."],[1,"(24) 2-[4-(Ethylthio)-2,5-dimethoxyphenyl]ethanamine (2C–T–2)."],[1,"(25) 2-[4-(Isopropylthio)-2,5-dimethoxyphenyl]ethanamine (2C–T–4)."],[1,"(26) 2-(2,5-Dimethoxyphenyl)ethanamine (2C–H)."],[1,"(27) 2-(2,5-Dimethoxy-4-nitro-phenyl)ethanamine (2C–N)."],[1,"(28) 2-(2,5-Dimethoxy-4-(n)-propylphenyl)ethanamine (2C–P)."],[0,"(d)(1) Unless specifically exempted or unless listed in another schedule, any material, compound, mixture, or preparation which contains any quantity of cannabimimetic agents, or which contains their salts, isomers, and salts of isomers whenever the existence of such salts, isomers, and salts of isomers is possible within the specific chemical designation."],[0,"(2) In paragraph (1):"],[1,"(A) The term \"cannabimimetic agents\" means any substance that is a cannabinoid receptor type 1 (CB1 receptor) agonist as demonstrated by binding studies and functional assays within any of the following structural classes:"],[2,"(i) 2-(3-hydroxycyclohexyl)phenol with substitution at the 5-position of the phenolic ring by alkyl or alkenyl, whether or not substituted on the cyclohexyl ring to any extent."],[2,"(ii) 3-(1-naphthoyl)indole or 3-(1-naphthylmethane)indole by substitution at the nitrogen atom of the indole ring, whether or not further substituted on the indole ring to any extent, whether or not substituted on the naphthoyl or naphthyl ring to any extent."],[2,"(iii) 3-(1-naphthoyl)pyrrole by substitution at the nitrogen atom of the pyrrole ring, whether or not further substituted in the pyrrole ring to any extent, whether or not substituted on the naphthoyl ring to any extent."],[2,"(iv) 1-(1-naphthylmethylene)indene by substitution of the 3-position of the indene ring, whether or not further substituted in the indene ring to any extent, whether or not substituted on the naphthyl ring to any extent."],[2,"(v) 3-phenylacetylindole or 3-benzoylindole by substitution at the nitrogen atom of the indole ring, whether or not further substituted in the indole ring to any extent, whether or not substituted on the phenyl ring to any extent."],[1,"(B) Such term includes—"],[2,"(i) 5-(1,1-dimethylheptyl)-2-[(1R,3S)-3-hydroxycyclohexyl]-phenol (CP–47,497);"],[2,"(ii) 5-(1,1-dimethyloctyl)-2-[(1R,3S)-3-hydroxycyclohexyl]-phenol (cannabicyclohexanol or CP–47,497 C8-homolog);"],[2,"(iii) 1-pentyl-3-(1-naphthoyl)indole (JWH–018 and AM678);"],[2,"(iv) 1-butyl-3-(1-naphthoyl)indole (JWH–073);"],[2,"(v) 1-hexyl-3-(1-naphthoyl)indole (JWH–019);"],[2,"(vi) 1-[2-(4-morpholinyl)ethyl]-3-(1-naphthoyl)indole (JWH–200);"],[2,"(vii) 1-pentyl-3-(2-methoxyphenylacetyl)indole (JWH–250);"],[2,"(viii) 1-pentyl-3-[1-(4-methoxynaphthoyl)]indole (JWH–081);"],[2,"(ix) 1-pentyl-3-(4-methyl-1-naphthoyl)indole (JWH–122);"],[2,"(x) 1-pentyl-3-(4-chloro-1-naphthoyl)indole (JWH–398);"],[2,"(xi) 1-(5-fluoropentyl)-3-(1-naphthoyl)indole (AM2201);"],[2,"(xii) 1-(5-fluoropentyl)-3-(2-iodobenzoyl)indole (AM694);"],[2,"(xiii) 1-pentyl-3-[(4-methoxy)-benzoyl]indole (SR–19 and RCS–4);"],[2,"(xiv) 1-cyclohexylethyl-3-(2-methoxyphenylacetyl)indole (SR–18 and RCS–8); and"],[2,"(xv) 1-pentyl-3-(2-chlorophenylacetyl)indole (JWH–203)."],[0,"(a) Unless specifically excepted or unless listed in another schedule, any of the following substances whether produced directly or indirectly by extraction from substances of vegetable origin, or independently by means of chemical synthesis, or by a combination of extraction and chemical synthesis:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/812?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§812. Schedules of controlled substances","tname":"Food and Drugs","by":{"0":"4","1":"1, 13, 28, 13, 28, 33","2":"42","4":"15"}},{"t":"reg","label":"28 C.F.R. § 0.100","url":"https://www.ecfr.gov/current/title-28/section-0.100","subs":["(b)"],"by":{"0":"4"}},{"t":"reg","label":"65 Fed. Reg. 13,235","url":"https://www.govinfo.gov/link/fr/65/13235","by":{"0":"23","3":"15"}},{"t":"reg","label":"67 Fed. Reg. 59,161","url":"https://www.govinfo.gov/link/fr/67/59161","by":{"0":"23"}},{"t":"reg","label":"69 Fed. Reg. 12,794","url":"https://www.govinfo.gov/link/fr/69/12794","by":{"0":"23","3":"16"}},{"t":"reg","label":"76 Fed. Reg. 65,371","url":"https://www.govinfo.gov/link/fr/76/65371","by":{"0":"24","3":"16"}},{"t":"case","label":"Archambault v. United States","cite":"224 F.2d 925","y":1955,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/224/925/","by":{"1":"20, 21"}},{"t":"case","label":"Atchison, T. & S.F. Ry. Co. v. Scarlett","cite":"300 U.S. 471","y":1937,"id":"scdb/1936-076","sc":1,"sum":"(1) A side ladder of a freight car complied with the Act, though between it and the side of the car was a diagonal brace rod, which the ladder cleared by two and three-quarter inches. P. 474. (2) The brace rod was not a part of the ladder. P. 474. (3) Long-continued use of brace rods of the type here involved, in the same relation to the ladder, without change of its order by the Interstate Commerce Commission, is …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20","4":"9"}},{"t":"case","label":"Carr v. United States","cite":"560 U.S. 438","y":2010,"id":"2009/08-1301","sc":1,"op":3,"sum":"The Court held that the Sex Offender and Registration Act does not apply to sex offenders' interstate travel that occurred before the Act's effective date.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Custis v. United States","cite":"511 U.S. 485","y":1994,"id":"1993/93-5209","sc":1,"op":2,"sum":"After the jury convicted petitioner Custis of possession of a firearm by a felon and another federal crime, the Government relied on his prior state-court convictions for robbery in Pennsylvania and for burglary and attempted burglary in Maryland to support a motion under the Armed Career Criminal Act of 1984, 18 U. S. C. § 924(e) (ACCA), which provides for enhancement of the sentence of a convicted firearms …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"15, 25"}},{"t":"case","label":"Dubin v. United States","cite":"143 S. Ct. 1557","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"Fourche River Lumber Co. v. Bryant Lumber Co.","cite":"230 U.S. 316","y":1913,"id":"scdb/1912-288","sc":1,"sum":"— Decided June 9, 1913.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Gryger v. Burke","cite":"334 U.S. 728","y":1948,"id":"scdb/1947-106","sc":1,"ar":3,"sum":"Petitioner was charged and convicted in a state court of Pennsylvania of being a fourth offender and sentenced to life imprisonment. In the proceeding on the fourth-offender charge, the only question of fact before the court was whether he was the same person who was convicted in four previous cases, and this he admitted and does not now deny.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"(Curtis) Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"1":"17, 22, 26"}},{"t":"case","label":"(Robert) Johnson v. United States","cite":"544 U.S. 295","y":2005,"id":"2004/03-9685","sc":1,"op":1,"sum":"The Court held that by waiting until more than three years after his federal sentence, Johnson failed to show due diligence in seeking to have his original state convictions vacated.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"(Samuel) Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"op":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"1":"27","2":"36","3":"13"}},{"t":"case","label":"Kolender v. Lawson","cite":"461 U.S. 352","y":1983,"id":"1982/81-1320","sc":1,"sum":"The law was unconstitutionally vague because it gave excessive discretion to the police (in the absence of probable cause for an arrest) whether to stop and interrogate a suspect or leave him alone. The majority hinted that the California statute compromised the constitutional right to freedom of movement.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Lora v. United States","cite":"143 S. Ct. 1713","y":2023,"id":"2022/22-49","sc":1,"sum":"The bar on imposition of concurrent sentences in 18 U. S. C. §924(c)(1)(D)(ii) does not apply to a sentence for a §924(j) conviction; a §924(j) sentence can run either concurrently with or consecutively to another sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"McBoyle v. United States","cite":"283 U.S. 25","y":1931,"id":"scdb/1930-139","sc":1,"sum":"The National Motor Vehicle Theft Act, U. S. C., Title 18, § 408, which punishes whoever transports, or causes to be transported, in interstate or foreign commerce a motor vehicle knowing it to have been stolen, and which defines \"motor vehicle\" as including \"an automobile, automobile truck, automobile wagon, motor cycle, or any other self-propelled vehicle not designed for running on rails,\" does not apply to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Percoco v. United States","cite":"143 S. Ct. 1130","y":2023,"id":"2022/21-1158","sc":1,"sum":"Jury instructions on the legal standard for finding that a private citizen owes the government a duty of honest services based on the Second Circuit’s decision in United States v. Margiotta, 688 F. 2d 108 (1982), were erroneous.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"Pereida v. Wilkinson","cite":"141 S. Ct. 754","y":2021,"id":"2020/19-438","sc":1,"sum":"A nonpermanent resident seeking to cancel a lawful removal order fails to carry his burden of showing that he has not been convicted of a disqualifying offense when the statutory conviction on his record is ambiguous regarding whether a disqualifying offense formed the basis of his conviction.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Peugh v. United States","cite":"569 U.S. 530","y":2013,"id":"2012/12-62","sc":1,"ar":2,"sum":"The Court found that using the U.S. Sentencing Guidelines at the time of the sentencing for a crime rather than at the time of the offense is a violation of the ex post facto clause.","sumSrc":"Oyez","by":{"1":"17","2":"39","3":"13"}},{"t":"case","label":"Rummel v. Estelle","cite":"445 U.S. 263","y":1980,"id":"1979/78-6386","sc":1,"sum":"In a 5-to-4 decision, the Court held that the life sentence imposed by Texas law did not constitute cruel and unusual punishment under the Eighth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"State v. Dickey","cite":"928 So. 2d 1193","y":2006,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/928/1193/","by":{"1":"31"}},{"t":"case","label":"United States v. Brown","cite":"47 F.4th 147","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/47/147/","op":1,"by":{"1":"6, 12"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"14, 37"}},{"t":"case","label":"United States v. Hope","cite":"28 F.4th 487","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/28/487/","by":{"1":"6","3":"18"}},{"t":"case","label":"United States v. Perez","cite":"46 F.4th 691","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/46/691/","op":1,"by":{"1":"6"}},{"t":"case","label":"United States v. R.L.C.","cite":"503 U.S. 291","y":1992,"id":"1991/90-1577","sc":1,"sum":"The judgment is affirmed. 915 F. 2d 320, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"United States v. Reeves","cite":"695 F.3d 637","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/695/637/","by":{"1":"31"}},{"t":"case","label":"United States v. Robinson","cite":"2019 WL 4409462","y":2019,"court":"D.S.C. Sept. 16","by":{"1":"31"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"United States v. Springfield","cite":"337 F.3d 1175","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/337/1175/","by":{"1":"33"}},{"t":"case","label":"United States v. Williams","cite":"48 F.4th 1125","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/48/1125/","by":{"1":"6, 19","4":"11"}},{"t":"case","label":"Warden, Lewisburg Penitentiary v. Marrero","cite":"417 U.S. 653","y":1974,"id":"1973/73-831","sc":1,"sum":"The Comprehensive Drug Abuse Prevention and Control Act of 1970, which became effective May 1, 1971, makes parole under the general parole statute, 18 U. S. C. § 4202, available for almost all narcotics offenders. Respondent, who had been sentenced before May 1, 1971, and was ineligible for parole under 26 U. S. C. § 7237 (d), which was repealed by the 1970 Act, sought habeas corpus in the District Court, claiming …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17","2":"41"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"op":3,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25, 33, 38","3":"13, 18"}},{"t":"const","label":"Amendment V","clauses":[["double-jeopardy","Double Jeopardy Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"26"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"31","4":"11"}},{"t":"const","label":"Article I, Section 10, Clause 10","by":{"1":"17, 18"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)","(b)(1)(C)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"1":"14, 16","2":"3, 7, 7","4":"3, 3"}},{"t":"usc","label":"21 U.S.C. § 848","url":"https://www.law.cornell.edu/uscode/text/21/848","by":{"1":"16"}},{"t":"usc","label":"21 U.S.C. § 960","url":"https://www.law.cornell.edu/uscode/text/21/960","subs":["(b)(1)(A)"],"by":{"1":"16"}},{"t":"usc","label":"21 U.S.C. § 1010","url":"https://www.law.cornell.edu/uscode/text/21/1010","subs":["(b)(1)(A)"],"by":{"1":"16"}},{"t":"law","label":"Pub. L. No. 106-172","url":"https://www.govinfo.gov/link/plaw/106/public/172","by":{"1":"32"}},{"t":"usc","label":"18 U.S.C. § 342","url":"https://www.law.cornell.edu/uscode/text/18/342","stext":{"head":"§342. Operation of a common carrier under the influence of alcohol or drugs","paras":[[0,"Whoever operates or directs the operation of a common carrier while under the influence of alcohol or any controlled substance (as defined in section 102 of the Controlled Substances Act (21 U.S.C. 802)), shall be imprisoned not more than fifteen years or fined under this title, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/342?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§342. Operation of a common carrier under the influence of alcohol or drugs","tname":"Crimes and Criminal Procedure","by":{"1":"14"}},{"t":"usc","label":"18 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/18/521","subs":["(c)(1)"],"by":{"1":"14"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)","(g)","(j)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"1":"3","2":"7, 7, 7","3":"18","4":"17"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"1"}},{"t":"reg","label":"21 C.F.R. pt. 1308","url":"https://www.ecfr.gov/current/title-21/part-1308","by":{"1":"28","2":"41","3":"15, 15, 16"}},{"t":"reg","label":"21 C.F.R. § 1308.12","url":"https://www.ecfr.gov/current/title-21/section-1308.12","subs":["(b)(4)(ii)","(e)(3)","(e)(4)","(e)(5)"],"by":{"1":"5","3":"15, 14, 15"}},{"t":"reg","label":"52 Fed. Reg. 38225","url":"https://www.govinfo.gov/link/fr/52/38225","by":{"1":"28, 35"}},{"t":"reg","label":"80 Fed. Reg. 54715","url":"https://www.govinfo.gov/link/fr/80/54715","by":{"1":"5","2":"11"}},{"t":"reg","label":"87 Fed. Reg. 34166","url":"https://www.govinfo.gov/link/fr/87/34166","by":{"1":"35"}},{"t":"case","label":"Caraco Pharm. Labs., Ltd. v. Novo Nordisk A/S","cite":"566 U.S. 399","y":2012,"id":"2011/10-844","sc":1,"sum":"The Court held that counterclaims that challenge unpatented uses of generic drugs, even if other approved uses are still under patent, are allowable under the Hatch-Waxman Act.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Dahda v. United States","cite":"138 S. Ct. 1491","y":2018,"id":"2017/17-43","sc":1,"sum":"The Court decided that wiretap orders authorized by a judge for the federal district of Kansas in a government investigation of a suspected Kansas drug distribution ring were not facially insufficient because they did not lack any information that the wiretap statute required them to include, and because the challenged language permitting interception outside the court’s territorial jurisdiction was surplus.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Kawashima v. Holder","cite":"565 U.S. 478","y":2012,"id":"2011/10-577","sc":1,"sum":"The Court held that filing a false tax return in violation of 26 U.S.C. Section 7206 qualifies as an aggravated felony under the Immigration and Nationality Act if the Government's revenue loss exceeds $10,000.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"2":"33, 43"}},{"t":"case","label":"Mellouli v. Lynch","cite":"575 U.S. 798","y":2015,"id":"2014/13-1034","sc":1,"sum":"The Government must prove the connection between a state drug paraphernalia conviction and a substance listed in the Controlled Substances Act to trigger deportability under the Immigration and Nationality Act.","sumSrc":"Oyez","by":{"2":"15, 16, 29, 34, 35, 37","3":"19, 20","4":"7, 9, 10"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"op":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"United States v. Clark","cite":"46 F.4th 404","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/46/404/","by":{"2":"37"}},{"t":"case","label":"United States v. New York Tel. Co.","cite":"434 U.S. 159","y":1977,"id":"1977/76-835","sc":1,"sum":"On the basis of an FBI affidavit stating that certain individuals were conducting an illegal gambling enterprise at a specified New York City address and that there was probable cause to believe that two telephones with different numbers were being used there to further the illegal activity, the District Court authorized the FBI to install and use pen registers with respect to the two telephones, and directed …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Village of Hoffman Estates v. The Flipside, Hoffman Estates, Inc.","cite":"455 U.S. 489","y":1982,"id":"1981/80-1681","sc":1,"sum":"The ordinance is not facially overbroad or vague but is reasonably clear in its application to appellee.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"2":"33, 4"}},{"t":"law","label":"Firearms Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/458","by":{"2":"4"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","by":{"2":"33"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(B)(i)"],"by":{"2":"16, 34"}},{"t":"law","label":"Maritime Drug Law Enforcement Act, Pub. L. No. 96-350","url":"https://www.govinfo.gov/link/statute/94/1159","by":{"2":"28"}},{"t":"law","label":"Pub. L. No. 112-144","url":"https://www.govinfo.gov/link/plaw/112/public/144","by":{"2":"38"}},{"t":"reg","label":"82 Fed. Reg. 12,171","url":"https://www.govinfo.gov/link/fr/82/12171","by":{"2":"38"}},{"t":"case","label":"Blakely v. Washington","cite":"542 U.S. 296","y":2004,"id":"2003/02-1632","sc":1,"sum":"The Court held that an exceptional sentence increase based on the judge's determination that Blakely had acted with \"deliberate cruelty\" violated Blakely's Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"sum":"The Court found that the \"failure to report\" crime does not satisfy the Armed Career Criminals Act's (ACCA) \"crime of violence\" definition.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Chazen v. Marske","cite":"938 F.3d 851","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/938/851/","by":{"3":"14"}},{"t":"case","label":"Henderson v. United States","cite":"568 U.S. 266","y":2013,"id":"2012/11-9307","sc":1,"sum":"The Court held that the determination of “plain error” is made during the appellate review, not during the trial.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"United States v. Crowder","cite":"87 F.3d 1405","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/87/1405/","by":{"3":"17"}},{"t":"case","label":"United States v. Heilman","cite":"377 F. App’x 157","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/377/157/","by":{"3":"18"}},{"t":"case","label":"United States v. Rice","cite":"259 F. App’x 300","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/259/300/","by":{"3":"18"}},{"t":"case","label":"Unites States v. West","cite":"563 F. App’x 745","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/563/745/","by":{"3":"18"}},{"t":"law","label":"Pub. L. No. 111-220","url":"https://www.govinfo.gov/link/plaw/111/public/220","by":{"3":"11"}},{"t":"reg","label":"21 C.F.R. § 1308.11","url":"https://www.ecfr.gov/current/title-21/section-1308.11","subs":["(d)(47)","(e)(1)","(e)(11)","(g)(4)","(g)(7)"],"by":{"3":"14, 14, 15, 15, 16"}},{"t":"case","label":"John P. MacKenzie, Hamm v. City of Roclk Hill and the Federal Savings Statute","cite":"54 Geo. L.J. 173","y":1965,"url":"https://www.courtlistener.com/c/Geo.%20L.J./54/173/","by":{"3":"10"}},{"t":"case","label":"CompSource Mut. Ins. Co. v. State ex rel. Okla. Tax Comm’n","cite":"435 P.3d 90","y":2018,"court":"Okla.","url":"https://www.courtlistener.com/c/P.3d/435/90/","by":{"4":"15"}},{"t":"case","label":"Dir., Office of Workers’ Comp. Programs, U.S. Dep’t of Labor v. Peabody Coal Co.","cite":"554 F.2d 310","y":1977,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/554/310/","by":{"4":"15"}},{"t":"case","label":"George Williams College v. Village of Williams Bay","cite":"7 N.W.2d 891","y":1943,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/7/891/","op":1,"by":{"4":"15"}},{"t":"case","label":"Haw. Providers Network, Inc. v. AIG Haw. Ins. Co.","cite":"98 P.3d 233","y":2004,"court":"Haw.","url":"https://www.courtlistener.com/c/P.3d/98/233/","by":{"4":"15"}},{"t":"case","label":"Interstate Consol. St. Ry. Co. v. Massachusetts","cite":"207 U.S. 79","y":1907,"id":"scdb/1907-008","sc":1,"sum":"Requirements contained in another statute or document may be incorporated in a charter by generic or specific reference and, if clearly identified, the charter has the same effect as if it itself contained the restrictive words, and the question of the constitutionality of the statute referredto is immaterial.","sumSrc":"Headnote (U.S. Reports)","by":{"4":"9"}},{"t":"case","label":"Nichols v. United States","cite":"511 U.S. 738","y":1994,"id":"1993/92-8556","sc":1,"op":2,"ar":1,"sum":"After petitioner Nichols pleaded guilty to federal felony drug charges, he was assessed criminal history points under the United States Sentencing Guidelines, including one point for a state misdemeanor conviction for driving while under the influence (DUI), for which he was fined but not incarcerated. That point increased the maximum sentence of imprisonment from 210 to 235 months. Petitioner objected to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"12"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"sum":"The Court held that counsel must inform a client whether or not his plea carries a risk of deportation under the Sixth Amendment.","sumSrc":"Oyez","by":{"4":"11"}},{"t":"case","label":"Panama R. Co. v. Johnson","cite":"264 U.S. 375","y":1924,"id":"scdb/1923-100","sc":1,"op":1,"sum":"1. As a general rule, where existing legislation on a particular subject has been systematically revised and restated in a comprehensive general statute, such as the Judicial Code, subsequent enactments touching that subject are to be construed and applied in harmony with the general statute, save as they clearly manifest a different purpose.","sumSrc":"Headnote (U.S. Reports)","by":{"4":"8"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"17"}},{"t":"case","label":"U.S. Dep’t of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"sum":"Congress has not waived the National Government's sovereign immunity from liability for civil fines imposed by a State for past violations of the CWA or RCRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"8"}},{"t":"case","label":"United States v. Bryant","cite":"579 U.S. 140","y":2016,"id":"2015/15-420","sc":1,"op":3,"sum":"The Court determined that the use of an uncounseled conviction in tribal court proceedings that complied with the Indian Civil Rights Act of 1968 (ICRA) as a predicate offense under 18 U.S.C. 117(a) did not violate the Sixth Amendment.","sumSrc":"Oyez","by":{"4":"12"}},{"t":"case","label":"United States v. Reynolds","cite":"215 F.3d 1210","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/215/1210/","by":{"4":"13"}},{"t":"const","label":"Article I, Section 9, Clause 3","clauses":[["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"]],"text":"No Bill of Attainder or ex post facto Law shall be passed.","by":{"4":"7, 18"}},{"t":"usc","label":"21 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/21/844","subs":["(a)"],"by":{"4":"17"}},{"t":"usc","label":"21 U.S.C. § 859","url":"https://www.law.cornell.edu/uscode/text/21/859","subs":["(b)"],"by":{"4":"17"}},{"t":"usc","label":"21 U.S.C. § 860","url":"https://www.law.cornell.edu/uscode/text/21/860","subs":["(b)"],"by":{"4":"17"}},{"t":"usc","label":"21 U.S.C. § 861","url":"https://www.law.cornell.edu/uscode/text/21/861","subs":["(c)"],"by":{"4":"17"}},{"t":"law","label":"Armed Career Criminal Act, Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2185","by":{"4":"1–9, 11–19"}}]};